import json; import sys; from pathlib import Path; import pytest; sys.path.insert(0, str(Path(__file__).resolve().parents[2])); from common.testing.coverage import calculate_unified_coverage as cuc
def _cov_comp(total: int, covered: int, pct: float | None=None) -> dict[str, object]: p = round(covered / max(total, 1) * 100, 2) if pct is None else pct; return {'total_lines': total, 'covered_lines': covered, 'coverage_percent': p}
def _cov_report(b: dict, fe: dict, t: dict, pct: float | None=None, covered: int | None=None) -> dict[str, object]: tot = b.get('total_lines', 0) + fe.get('total_lines', 0) + t.get('total_lines', 0); cov = b.get('covered_lines', 0) + fe.get('covered_lines', 0) + t.get('covered_lines', 0) if covered is None else covered; p = round(cov / max(tot, 1) * 100, 2) if pct is None else pct; return {'coverage_percent': p, 'total_lines': tot, 'covered_lines': cov, 'breakdown': {'backend': b, 'frontend': fe, 'tools': t}}
