class TestBaselineComparison:
    SAMPLE_BASELINE = _cov_report(_cov_comp(5000, 4700, 94.0), _cov_comp(3000, 2494, 83.13), _cov_comp(2000, 1662, 83.1), 83.15, covered=8315)
