    def test_within_epsilon_jitter_floating_point_imprecision(self, tmp_path, monkeypatch): baseline_data = {'coverage_percent': 95.56, 'total_lines': 50000, 'covered_lines': 47780, 'breakdown': {'tools': _cov_comp(3399, 3140, 92.37)}}; self._setup_baseline(tmp_path, monkeypatch, baseline_data); current = {'tools': _cov_comp(3399, 3138, 92.32)}; monkeypatch.setattr(cuc, 'get_tools_coverage', lambda: current['tools']); assert cuc.main(['--gate-components', 'tools']) == 0
    def test_fails_when_unified_drops_below_baseline(self, tmp_path, monkeypatch, capfd): self._setup_baseline(tmp_path, monkeypatch); b, fe, t = (_cov_comp(5000, 4500, 90.0), _cov_comp(3000, 2400, 80.0), _cov_comp(2000, 1300, 65.0)); self._mock_coverage(monkeypatch, backend=b, frontend=fe, tools=t); assert cuc.main([]) == 1; captured = capfd.readouterr(); assert '82.0' in captured.err; assert '83.15' in captured.err; assert 'BASELINE COMPARISON' in captured.out; assert 'unified: current=8200/10000 (82.00%) baseline=8315/10000 (83.15%)' in captured.out; current_report = json.loads((tmp_path / 'unified-coverage.json').read_text()); assert current_report['covered_lines'] == 8200; assert current_report['total_lines'] == 10000
    def test_regression_output_lists_component_deltas_and_sources(self, tmp_path, monkeypatch, capfd): baseline_file = tmp_path / 'baseline.json'; baseline_file.write_text(json.dumps({'coverage_percent': 80.0, 'breakdown': {c: {'coverage_percent': 80.0} for c in ('backend', 'frontend', 'tools')}})); monkeypatch.setenv('BASELINE_FILE', str(baseline_file)); monkeypatch.setenv('COVERAGE_THRESHOLD', '0'); monkeypatch.setattr(cuc, 'ROOT_DIR', tmp_path); self._mock_coverage(monkeypatch, backend=_cov_comp(100, 70, 70.0), frontend=_cov_comp(100, 80, 80.0), tools=_cov_comp(100, 75, 75.0)); assert cuc.main([]) == 1; err = capfd.readouterr().err; assert 'Coverage regression detected by local deterministic gate' in err; assert 'baseline.json' in err; assert 'backend: current=70.00% baseline=80.00% delta=-10.00%' in err; assert 'tools: current=75.00% baseline=80.00% delta=-5.00%' in err; assert 'source=coverage/backend.lcov' in err; assert 'source=coverage/tools.lcov' in err
    def test_fails_when_backend_drops_despite_unified_ok(self, tmp_path, monkeypatch): self._setup_baseline(tmp_path, monkeypatch); self._mock_coverage(monkeypatch, backend=_cov_comp(5000, 4500, 90.0)); assert cuc.main([]) == 1
    def test_fails_when_frontend_drops(self, tmp_path, monkeypatch): self._setup_baseline(tmp_path, monkeypatch); self._mock_coverage(monkeypatch, backend=_cov_comp(5000, 4159, 83.18), frontend=_cov_comp(3000, 1800, 60.0)); assert cuc.main([]) == 1
