class TestRatchetMode:
    'AC-testing.diff-coverage.4'
    def _regressing_setup(self, tmp_path, monkeypatch): import re as _re; baseline_file = tmp_path / 'baseline.json'; baseline_file.write_text(json.dumps(_cov_report(_cov_comp(100, 80, 80.0), _cov_comp(100, 80, 80.0), _cov_comp(100, 80, 80.0), 80.0))); monkeypatch.setenv('BASELINE_FILE', str(baseline_file)); monkeypatch.setenv('COVERAGE_THRESHOLD', '0'); monkeypatch.delenv('COVERAGE_RATCHET_MODE', raising=False); monkeypatch.setattr(cuc, 'ROOT_DIR', tmp_path); monkeypatch.setattr(cuc, 'get_backend_coverage', lambda: _cov_comp(100, 70, 70.0)); ok = _cov_comp(100, 80, 80.0); monkeypatch.setattr(cuc, 'get_frontend_coverage', lambda: ok); monkeypatch.setattr(cuc, 'get_tools_coverage', lambda: ok); return _re
    def test_ratchet_report_mode_reports_regression_without_blocking(self, tmp_path, monkeypatch, capfd): _re = self._regressing_setup(tmp_path, monkeypatch); monkeypatch.setenv('COVERAGE_RATCHET_MODE', 'report'); assert cuc.main([]) == 0; err = capfd.readouterr().err; assert _re.search('(?i)report-only', err); assert _re.search('backend: current=70\\.00% baseline=80\\.00%', err); assert (tmp_path / 'unified-coverage.json').exists()
    def test_ratchet_block_mode_flag_blocks_regression(self, tmp_path, monkeypatch): self._regressing_setup(tmp_path, monkeypatch); assert cuc.main(['--ratchet-mode', 'block']) == 1
    def test_ratchet_default_mode_is_block(self, tmp_path, monkeypatch): self._regressing_setup(tmp_path, monkeypatch); assert cuc.main([]) == 1
    def test_ratchet_mode_flag_overrides_env(self, tmp_path, monkeypatch): self._regressing_setup(tmp_path, monkeypatch); monkeypatch.setenv('COVERAGE_RATCHET_MODE', 'block'); assert cuc.main(['--ratchet-mode', 'report']) == 0
    def test_report_mode_keeps_threshold_safety_net(self, tmp_path, monkeypatch): self._regressing_setup(tmp_path, monkeypatch); monkeypatch.setenv('COVERAGE_RATCHET_MODE', 'report'); monkeypatch.setenv('COVERAGE_THRESHOLD', '90'); assert cuc.main([]) == 1
    def test_invalid_ratchet_mode_env_fails_loudly(self, tmp_path, monkeypatch): self._regressing_setup(tmp_path, monkeypatch); monkeypatch.setenv('COVERAGE_RATCHET_MODE', 'sometimes'); assert cuc.main([]) == 2
def test_module_main_entry_point(tmp_path, monkeypatch): cov = {'total_lines': 100, 'covered_lines': 90, 'coverage_percent': 90.0}; monkeypatch.setattr(cuc, 'ROOT_DIR', tmp_path); monkeypatch.setenv('COVERAGE_THRESHOLD', '0'); monkeypatch.setenv('BASELINE_FILE', ''); monkeypatch.setattr(cuc, 'get_backend_coverage', lambda: cov); monkeypatch.setattr(cuc, 'get_frontend_coverage', lambda: cov); monkeypatch.setattr(cuc, 'get_tools_coverage', lambda: cov); assert cuc.main([]) == 0
